import math

# Registry of shape calculations
# Each shape maps to a dict with 'area' and 'perimeter' callables
SHAPES = {
    'circle': {
        'area': lambda a, b=None: math.pi * a * a,
        'perimeter': lambda a, b=None, c=None: 2 * math.pi * a
    },
    'rect': {
        'area': lambda a, b=None: a * b,
        'perimeter': lambda a, b=None, c=None: 2 * (a + b)
    },
    'tri': {
        'area': lambda a, b=None: 0.5 * a * b,
        'perimeter': lambda a, b=None, c=None: a + b + c
    }
}

def area(kind, a, b=None):
    if kind not in SHAPES:
        raise ValueError(f"Unknown shape: {kind}")
    return SHAPES[kind]['area'](a, b)

def perimeter(kind, a, b=None, c=None):
    if kind not in SHAPES:
        raise ValueError(f"Unknown shape: {kind}")
    return SHAPES[kind]['perimeter'](a, b, c)
```

